mapper.update:
update complaint
status = #{status,jdbcType=VARCHAR}, assignee_id = #{assigneeId,jdbcType=BIGINT}, merged_into_id = #{mergedIntoId,jdbcType=BIGINT}, updated_at = #{updatedAt,jdbcType=TIMESTAMP},
where id = #{id,jdbcType=BIGINT} and version = #{version,jdbcType=INTEGER}

mapper.select:
select c.id, c.event_id, c.reporter_id, c.description, c.status, c.assignee_id, c.merged_into_id, c.created_at, c.updated_at, c.version
from complaint c
left join complaint_event e on e.id = c.event_id

  and c.status = #{status,jdbcType=VARCHAR}
  and e.doctor_id = #{doctorId,jdbcType=BIGINT}

order by c.id desc
limit #{offset}, #{size}

select count(*) from complaint c
left join complaint_event e on e.id = c.event_id

  and c.status = #{status,jdbcType=VARCHAR}
  and e.doctor_id = #{doctorId,jdbcType=BIGINT}
